// The standing tracker, resolved to a NUMBER before the agent exists
// (task-postwork DESIGN §2): the agent is told where to log, and no longer
// carries the find-by-exact-title procedure that could match the wrong issue.
// A resolution that fails parks the item — handing off without the number sends
// an agent to invent a tracker, which is what this removes.
const context = [...(verdict.context ?? [])];
if (task.decl.tracker) {
  try {
    const tracker = await ensureTracker(gh, repo, task.decl.tracker);
    context.push(trackerContextLine(tracker));
  } catch (e) {
    await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN, claim,
      `Could not resolve this task's standing tracker: ${e.message}\n\nNothing was handed off. Re-queue this item (remove \`${NEEDS_HUMAN}\`, add \`${READY}\`) once the read works.`);
    return 'needs-human';
  }
}

