1	// The executor (tasks-dispatch DESIGN §6) — a pull worker over the queue. Each
2	// iteration: pick the next ready item, claim it by a verified lease, evaluate the
3	// precondition (THE only place it is ever evaluated), then on a go run prework and
4	// either converge (agentless) or hand off to an agent session; on a no-go roll a
5	// scheduled item to its next anchor with the reason on record.
6	//
7	// An executor's whole interface is issue read/write plus the repo at HEAD, which
8	// is what makes it platform-agnostic: the reference deployment is a job in the
9	// vendored workflows (the tick's post-tick drain, and a `labeled`-event run for
10	// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
11	// enumerates executors; identity is self-declared in the claim comment.
12	//
13	// The pure decisions live at the top and test with fixtures; the shell below is
14	// the GitHub/prework/invocation I/O around them.
15	
16	import { pathToFileURL } from 'node:url';
17	import { nextAnchor } from './anchors.mjs';
18	import { ensureTracker, trackerContextLine } from '../tracker.mjs';
19	import {
20	  READY, URGENT, EXECUTING, AGENT, BLOCKED, NEEDS_HUMAN, ORIGIN_SCHEDULE,
21	  OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE, QUEUE_LABELS,
22	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
23	  parseWorkItemTitle, parseWorkItemBody, withNotBefore, withSection, hasLabel,
24	} from './work-item.mjs';
25	
26	// How many items one executor run may take before it stops. Small on purpose: an
27	// executor is code iterating a queue, and more capacity is more executors, not a
28	// longer loop (DESIGN §10).
29	export const DEFAULT_MAX_ITEMS = 3;
30	
31	const titleOf = (item) => (item.title ?? '').trim();
32	const taskIdOf = (item) => {
33	  const p = parseWorkItemTitle(item.title);
34	  return p ? `${p.pack}/${p.task}` : null;
35	};
36	
37	// The pick order (DESIGN §6.1): urgent first, then oldest-created, with two skip
38	// rules read live at pick time.
39	//
40	//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
41	//    item executing or handed to an agent — one task, one execution at a time,
42	//    while a fan-out's distinct qualifiers still parallelize.
43	//  - THE `after` YIELD (S24): skip a scheduled item whose task declares `after:
44	//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
45	//    A rolled upstream (blocked until its next anchor: it declined this cycle)
46	//    does not block, and neither does one sitting `needs-human` — a broken
47	//    upstream must not halt its dependents indefinitely. Deliberately NOT a
48	//    `Blocked-by` edge: a standing item that rolls never closes, so blocked-by
49	//    would starve every dependent of a quiet upstream forever.
50	//
