// The standing-tracker resolver. What these pin is the two ways the agent-side
// procedure it replaces used to go wrong silently — a fuzzy title match landing on
// a sibling tracker, and a failed search reading as "no tracker exists" — plus the
// re-entrancy every executor-run helper owes (a reclaimed claim re-runs it).

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  pickTracker, ensureTracker, trackerFromEnv, writeTracker, trackerContextLine,
} from '../../engine/scheduler/tracker.mjs';

// A GitHub stand-in whose search is TEXT-ranked like the real one: it returns
// every title containing the query, in insertion order, so a test that passes here
// cannot be relying on the right answer coming back first.
function fakeGh(issues = [], { searchStatus = 200 } = {}) {
  const state = { issues: [...issues], seq: Math.max(0, ...issues.map((i) => i.number)), calls: [] };
  const gh = async (path, { method = 'GET', body } = {}) => {
    state.calls.push(`${method} ${path.split('?')[0]}`);
    if (path.startsWith('/search/issues')) {
      if (searchStatus !== 200) return { status: searchStatus, json: null };
      const q = decodeURIComponent(path);
      const term = /in:title "([^"]+)"/.exec(q)?.[1] ?? '';
      return { status: 200, json: { items: state.issues.filter((i) => i.title.includes(term)) } };
    }
    let m;
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)$/.exec(path))) {
      const issue = state.issues.find((i) => i.number === Number(m[1]));
      if (!issue) return { status: 404, json: null };
      if (method === 'PATCH') Object.assign(issue, body);
      return { status: 200, json: issue };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/comments$/.exec(path))) {
      const issue = state.issues.find((i) => i.number === Number(m[1]));
      issue.comments = [...(issue.comments ?? []), body.body];
      return { status: 201, json: {} };
    }
    if (path.endsWith('/issues') && method === 'POST') {
      const issue = { number: (state.seq += 1), title: body.title, body: body.body, state: 'open', comments: [] };
      state.issues.push(issue);
      return { status: 201, json: issue };
    }
    return { status: 404, json: null };
  };
  return { gh, state };
}

test('an exact title wins over a sibling the text search also returns', () => {
  const items = [
    { number: 5, title: 'Claudinite tracker: Tidy Issues', state: 'closed' },
    { number: 6, title: 'Claudinite tracker: Tidy PRs', state: 'closed' },
  ];
  assert.equal(pickTracker(items, 'Claudinite tracker: Tidy PRs').number, 6);
  // The failure this replaces: the agent takes the first hit and rewrites the
  // wrong dimension's tracker, with nothing anywhere going red.
  assert.equal(pickTracker(items, 'Claudinite tracker: Tidy Branches'), null);
});

test('the lowest number wins when a past race left two of the same title', () => {
  const items = [
    { number: 40, title: 'Claudinite tracker: Growth Dedup', state: 'closed' },
    { number: 12, title: 'Claudinite tracker: Growth Dedup', state: 'closed' },
  ];
  assert.equal(pickTracker(items, 'Claudinite tracker: Growth Dedup').number, 12);
});

test('an existing tracker is found in ANY state and nothing is created', async () => {
  // Closed is the resting state of every tracker, so a state-filtered lookup would
  // miss all of them and open a second one on every single run.
  const { gh, state } = fakeGh([{ number: 9, title: 'Claudinite tracker: Tidy PRs', state: 'closed' }]);
  const got = await ensureTracker(gh, 'o/r', 'Claudinite tracker: Tidy PRs');
  assert.deepEqual(got, { number: 9, created: false, duplicates: 0 });
  assert.deepEqual(state.calls.filter((c) => c.startsWith('POST')), []);
});

test('an absent tracker is created and closed in the same resolution', async () => {
  const { gh, state } = fakeGh();
  const got = await ensureTracker(gh, 'o/r', 'Claudinite tracker: Tidy PRs');
  assert.equal(got.created, true);
  const made = state.issues.find((i) => i.number === got.number);
  assert.equal(made.title, 'Claudinite tracker: Tidy PRs');
  assert.equal(made.state, 'closed');
  // The seed body says what the issue is, because whoever finds it next finds it
  // closed and empty.
  assert.match(made.body, /Standing tracker/);
});

test('resolving twice creates exactly one tracker', async () => {
  // Re-entrancy, not idempotence-by-luck: a reclaimed claim re-runs the executor
  // over its own half-done work, and a second tracker is a silent fork of the log.
  const { gh, state } = fakeGh();
  const first = await ensureTracker(gh, 'o/r', 'Claudinite tracker: Growth Extract');
  const second = await ensureTracker(gh, 'o/r', 'Claudinite tracker: Growth Extract');
  assert.equal(second.number, first.number);
  assert.equal(second.created, false);
  assert.equal(state.issues.length, 1);
});

test('a failed search THROWS rather than creating a second tracker', async () => {
  // The one that would be expensive to learn in production: a rate-limited search
  // reading as "nothing found" mints a new tracker every run it fails.
  const { gh, state } = fakeGh([{ number: 9, title: 'Claudinite tracker: Tidy PRs', state: 'closed' }], { searchStatus: 403 });
  await assert.rejects(() => ensureTracker(gh, 'o/r', 'Claudinite tracker: Tidy PRs'), /search returned 403/);
  assert.equal(state.issues.length, 1);
});

test('duplicates from a past race are reported, not silently ignored', async () => {
  const { gh } = fakeGh([
    { number: 12, title: 'Claudinite tracker: Growth Dedup', state: 'closed' },
    { number: 40, title: 'Claudinite tracker: Growth Dedup', state: 'closed' },
  ]);
  const got = await ensureTracker(gh, 'o/r', 'Claudinite tracker: Growth Dedup');
  assert.deepEqual({ number: got.number, duplicates: got.duplicates }, { number: 12, duplicates: 1 });
  assert.match(trackerContextLine(got), /1 other issue\(s\) share this title/);
});

test('the Context line carries the number and the never-touch-state contract', () => {
  const line = trackerContextLine({ number: 21 });
  assert.match(line, /Tracker: #21/);
  assert.match(line, /Never open, close or reopen it/);
});

test('a worker with no resolved tracker throws instead of falling back to a search', () => {
  for (const env of [{}, { CLAUDINITE_TRACKER: '' }, { CLAUDINITE_TRACKER: 'nope' }, { CLAUDINITE_TRACKER: '0' }]) {
    assert.throws(() => trackerFromEnv(env), /CLAUDINITE_TRACKER is not set/);
  }
  assert.equal(trackerFromEnv({ CLAUDINITE_TRACKER: '21' }), 21);
});

test('writeTracker replaces the body and appends at most one comment', async () => {
  const { gh, state } = fakeGh([{ number: 9, title: 'T', body: 'yesterday', state: 'closed', comments: [] }]);
  await writeTracker(gh, 'o/r', 9, { body: 'today' });
  await writeTracker(gh, 'o/r', 9, { body: 'today', comment: '2026-08-17 — ran' });
  const issue = state.issues[0];
  assert.equal(issue.body, 'today');
  assert.deepEqual(issue.comments, ['2026-08-17 — ran']);
  // The state is never touched, in either direction, by any write here.
  assert.equal(issue.state, 'closed');
});

test('a write that fails is reported, never swallowed', async () => {
  const { gh } = fakeGh();
  await assert.rejects(() => writeTracker(gh, 'o/r', 404, { body: 'x' }), /could not refresh tracker #404/);
});

