// --- the standing tracker (task-postwork DESIGN §2) ----------------------------
// A task that declares one gets its NUMBER; the agent never searches for a title.

test('a declared tracker is resolved once and reaches both phases', async () => {
  const repo = fakeRepo([
    workItem(1, 'a', ['task:ready', 'origin:schedule']),
    { number: 7, title: 'Claudinite tracker: Tidy PRs', labels: [], body: 'standing', state: 'closed' },
  ]);
  let sawTracker = null;
  await drive(repo, [task('a', {
    tracker: 'Claudinite tracker: Tidy PRs', prework: 'node w.mjs', prework_timeout: 60,
    precondition: () => ({ run: true, context: ['PRs to assess: #3.'] }),
  })], {
    runTaskPrework: async (_t, opts) => { sawTracker = opts.tracker; return { ok: true, agentRequested: true }; },
  });
  // Prework is handed the number rather than the title: both phases address the
  // same issue by construction, and no worker searches for it.
  assert.equal(sawTracker, 7);
  const body = repo.find(1).body;
  assert.match(body, /Tracker: #7/);
  // …and the precondition's own binding scope is still there, not replaced by it.
  assert.match(body, /PRs to assess: #3\./);
  assert.ok(repo.find(1).labels.includes('task:agent'));
});

test('a declared tracker that does not exist yet is created before the hand-off', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:ready', 'origin:schedule'])]);
  await drive(repo, [task('a', { tracker: 'Claudinite tracker: Tidy PRs' })]);
  const made = repo.state.issues.find((i) => i.title === 'Claudinite tracker: Tidy PRs');
  assert.ok(made, 'the tracker was created');
  assert.match(repo.find(1).body, new RegExp(`Tracker: #${made.number}`));
});

test('a tracker that cannot be resolved parks the item — neither phase runs blind', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:ready', 'origin:schedule'])]);
  repo.state.searchStatus = 403;
  let preworkRan = false;
  const done = await drive(repo, [task('a', { tracker: 'Claudinite tracker: Tidy PRs', prework: 'node w.mjs', prework_timeout: 60 })], {
    runTaskPrework: async () => { preworkRan = true; return { ok: true, agentRequested: true }; },
  });
