p='packs-tests/tidy-repo/pack.test.mjs'
s=open(p).read()
old = """test('each worker reconciles its OWN tracker by exact title — three tasks never race on one body', () => {
  const titles = {
    'tidy-issues': 'Claudinite tracker: Tidy Issues',
    'tidy-prs': 'Claudinite tracker: Tidy PRs',
    'tidy-branches': 'Claudinite tracker: Tidy Branches',
  };
  for (const [id, title] of Object.entries(titles)) {
    const worker = readFileSync(join(taskDir(id), 'task.md'), 'utf8');
    assert.ok(worker.includes(`\\`${title}\\``), `${id}/task.md does not name its tracker \\`${title}\\``);
    // The tracker's state carries no meaning, so no worker may open or close it.
    assert.match(worker, /Never open, close, or reopen the tracker/);
  }
});"""
new = """test('each task DECLARES its OWN tracker — three tasks never race on one body', () => {
  // The title is a declaration, not prose: the scheduler resolves it to a number
  // before either phase runs, so a doc that named one could only disagree with it.
  const declared = {
    'tidy-issues': tidyIssues.tracker,
    'tidy-prs': tidyPrs.tracker,
    'tidy-branches': tidyBranches.tracker,
  };
  assert.deepEqual(declared, {
    'tidy-issues': 'Claudinite tracker: Tidy Issues',
    'tidy-prs': 'Claudinite tracker: Tidy PRs',
    'tidy-branches': 'Claudinite tracker: Tidy Branches',
  });
  assert.equal(new Set(Object.values(declared)).size, 3, 'two dimensions share a tracker body');
  for (const id of Object.keys(declared)) {
    const worker = readFileSync(join(taskDir(id), 'task.md'), 'utf8');
    // The number arrives as binding scope; no agent goes looking for a title.
    assert.match(worker, /Tracker: #<n>/, `${id}/task.md does not read its tracker from Context`);
    // The tracker's state carries no meaning, so no worker may open or close it.
    assert.match(worker, /Never open, close, or reopen the tracker/);
  }
});"""
assert old in s
open(p,'w').write(s.replace(old,new))

p='packs-tests/jwt/pack.test.mjs'
s=open(p).read()
old = """test('jwt-advisory-watch: worker doc present, reconciles its own tracker by exact title', () => {
  const worker = readFileSync(join(PACK_DIR, 'tasks/jwt-advisory-watch', advisoryWatch.agent_instructions), 'utf8');
  assert.ok(worker.includes('`Claudinite tracker: JWT advisory watch`'));"""
new = """test('jwt-advisory-watch: worker doc present, logs to the tracker it declares', () => {
  const worker = readFileSync(join(PACK_DIR, 'tasks/jwt-advisory-watch', advisoryWatch.agent_instructions), 'utf8');
  // The title is declared and resolved to a number before the agent starts; the
  // doc reads that number out of Context rather than searching for the title.
  assert.equal(advisoryWatch.tracker, 'Claudinite tracker: JWT advisory watch');
  assert.match(worker, /Tracker: #<n>/);"""
assert old in s
open(p,'w').write(s.replace(old,new))
PY
node --test $(git ls-files '*.test.mjs') 2>&1 | grep -E "^not ok|# (tests|pass|fail)"

