toolUseResult.originalFile:
// A task's STANDING TRACKER — the one issue a recurring task logs every run to,
// resolved in code before the agentic phase starts.
//
// Seven tasks used to make their agent do this, in seven near-identical
// paragraphs: *find the issue titled exactly `<title>` — by that exact title,
// never a fuzzy match, never a hard-coded number; create it already closed if
// absent.* None of it is judgment. It is a search, a create-if-absent and a read,
// and it was the agent's first act in a phase that should hold only what a second
// reasonable agent could disagree about (task-postwork DESIGN §2). Worse, the one
// way it fails is silent: an agent that fuzzy-matches the wrong issue rewrites the
// wrong body, and nothing anywhere goes red.
//
// So the task declares the title (`tracker` in task.mjs) and this module resolves
// it to a NUMBER that reaches the agent in the item's binding Context. The agent
// is told where to write; it never decides where.
//
// TWO PROPERTIES THIS IS SHAPED AROUND:
//
//   EXACT MATCH, NEVER THE SEARCH'S OWN RANKING. GitHub's `in:title` search is a
//   text match, so `Claudinite tracker: Tidy PRs` also returns `Claudinite
//   tracker: Tidy Issues` — and on a repo running three tidy dimensions the
//   top-ranked hit is not reliably the right one. Every result is re-filtered here
//   on the trimmed title being EQUAL to the declared one, and a query that returns
//   nothing exact creates rather than guesses.
//
//   CREATED CLOSED, AND THE STATE NEVER MEANS ANYTHING AFTER THAT. A tracker is a
//   living document whose BODY is the current picture; its open/closed state
//   carries no information, and a task that opened one would be filing a
//   permanently-open issue on every member repo. Created closed is the same
//   posture as "nothing here needs a human right now", and nothing — this module
//   included — ever reopens or re-closes it afterwards.
//
// The search index lags a create by seconds to minutes, so two runs racing the
// same absent tracker CAN produce two issues. That is why resolution prefers the
// LOWEST number among exact matches: every later run converges on the first one,
// and the duplicate is inert (nothing writes to it again) rather than a fork.

// The exact-title filter, pure so the ranking question is settled in a test rather
// than against a live repo's issue list. Lowest number wins — the original.
export function pickTracker(items, title) {
  const want = title.trim();
  const exact = (items ?? [])
    .filter((i) => (i.title ?? '').trim() === want)
    .map((i) => ({ number: i.number, state: i.state }));
  if (!exact.length) return null;
  return exact.sort((a, b) => a.number - b.number)[0];
}

// Resolve `title` to an issue number in `repo`, creating the tracker if no issue
// carries that exact title. Returns { number, created, duplicates } — `duplicates`
// counting the extra exact matches a past race left behind, so a run can say so
// rather than the operator finding out from a tracker that stopped updating.
//
// A failed CREATE throws: the number is binding scope for the agentic phase, and a
// hand-off that names no tracker sends an agent to invent one — which is the
// behaviour this module exists to remove.
export async function ensureTracker(gh, repo, title) {
  const want = title.trim();
  const q = encodeURIComponent(`repo:${repo} in:title "${want}"`);
  const { status, json } = await gh(`/search/issues?q=${q}&per_page=100`);
  // A search that FAILED is not a search that found nothing: creating here would
  // mint a second tracker every time the API rate-limits.
  if (status !== 200 || !Array.isArray(json?.items)) {
    throw new Error(`could not search for the tracker ${JSON.stringify(want)}: search returned ${status}`);
  }
  const exact = json.items.filter((i) => (i.title ?? '').trim() === want);
  const found = pickTracker(exact, want);
  if (found) return { number: found.number, created: false, duplicates: exact.length - 1 };

  const created = await gh(`/repos/${repo}/issues`, {
    method: 'POST',
    body: { title: want, body: trackerSeedBody(want) },
  });
  if (created.status >= 300 || !created.json?.number) {
    throw new Error(`could not create the tracker ${JSON.stringify(want)}: create returned ${created.status}`);
  }
  const number = created.json.number;
  // Closed immediately, and this is the only state write in the tracker's life.
  // A failure here is not worth failing the run over — the tracker exists and is
  // writable, which is what the agentic phase needs.
  const closed = await gh(`/repos/${repo}/issues/${number}`, {
    method: 'PATCH',
    body: { state: 'closed', state_reason: 'completed' },
  });
  return { number, created: true, duplicates: 0, leftOpen: closed.status >= 300 };
}

// What a freshly-created tracker says before its first run writes to it. It names
// its own contract, because the next person to find it will find it closed and
// empty and wonder whether it is dead.
export function trackerSeedBody(title) {
  return [
    `Standing tracker for the Claudinite task that logs to **${title}**.`,
    '',
    'This issue is a living document: the **body** is rewritten to the current picture each run,',
    'and each run adds a dated comment. Its closed state carries no meaning — nothing opens,',
    'closes or reopens it, and no run should be read as "resolved" because it is closed.',
    '',
    '_No run has written here yet._',
  ].join('\n') + '\n';
}

// The number the engine resolved for THIS run, for a prework worker that writes to
// the tracker itself. Throwing beats defaulting: the variable is set whenever the
// task declares `tracker`, so an empty one means the worker is running outside the
// scheduler (or the declaration was dropped), and searching for the title as a
// fallback is what this module exists to stop.
export function trackerFromEnv(env = process.env) {
  const raw = (env.CLAUDINITE_TRACKER ?? '').trim();
  const n = Number(raw);
  if (!raw || !Number.isInteger(n) || n <= 0) {
    throw new Error('CLAUDINITE_TRACKER is not set — the scheduler sets it for a task that declares "tracker"');
  }
  return n;
}

// Write a run's state to the tracker: the BODY replaced with the current picture,
// and optionally one dated comment appended. Two writes, one contract — the body is
// the live snapshot, the comments are the trail — and the state is untouched, in
// either direction.
export async function writeTracker(gh, repo, number, { body, comment = null } = {}) {
  if (body !== undefined && body !== null) {
    const patched = await gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { body } });
    if (patched.status >= 300) throw new Error(`could not refresh tracker #${number}: PATCH returned ${patched.status}`);
  }
  if (comment) {
    const posted = await gh(`/repos/${repo}/issues/${number}/comments`, { method: 'POST', body: { body: comment } });
    if (posted.status >= 300) throw new Error(`could not comment on tracker #${number}: POST returned ${posted.status}`);
  }
  return number;
}

// The Context line the agent reads. One line, an identifier and its contract —
// never the content to write, which is the agentic phase's whole job.
export function trackerContextLine({ number, duplicates = 0 }) {
  const dup = duplicates > 0
    ? ` (${duplicates} other issue(s) share this title — a past race; this is the original, ignore the rest)`
    : '';
  return `Tracker: #${number} — log this run there${dup}. Never open, close or reopen it.`;
}

