2	// LIBRARY, not a phase: nothing in the scheduler knows a task has a tracker, no
3	// declaration carries one, and no task is expected to want one. A task that keeps
4	// an aggregated record calls these from its OWN prework and passes the number to
5	// its agentic phase through the ordinary hand-off payload (`delivered.issue`,
6	// rendered into the dispatch by prework-run.mjs / dispatch.mjs).
7	//
8	// It exists because two tasks had each grown a private copy of the same search, and
9	// the copies had already diverged in a way that matters — one filtered `is:open`,
10	// which never matches a tracker at rest and so opens a second one the moment
11	// anybody closes the first.
12	//
13	// TWO PROPERTIES THE LOOKUP IS SHAPED AROUND:
14	//
15	//   EXACT MATCH, NEVER THE SEARCH'S OWN RANKING. GitHub's `in:title` search is a
16	//   text match, so a title that is a prefix or near-twin of another task's comes
17	//   back too — and where sibling tasks keep sibling trackers, the top-ranked hit is
18	//   not reliably the right one. Every result is re-filtered on the trimmed title
19	//   being EQUAL to the one asked for.
20	//
21	//   A FAILED SEARCH IS NOT AN ABSENT TRACKER. `findTracker` returns null only for
22	//   a search that ran and matched nothing; anything else throws, because a caller
23	//   that treats a rate-limited search as "none exists" opens a fresh tracker on
24	//   every failure.
25	//
26	// Creation is deliberately a SEPARATE call. Whether a run with nothing to say
27	// should mint a tracker at all is the task's judgment — a sweep that found nothing
28	// may hold that its own scan is not news — so this module never creates as a side
29	// effect of looking.
30	
31	// The exact-title filter, pure so the ranking question is settled in a test rather
32	// than against a live repo's issue list. Lowest number wins: if a past race left
33	// two, every later run converges on the first and the duplicate stays inert.
34	export function pickTracker(items, title) {
35	  const want = title.trim();
36	  const exact = (items ?? [])
37	    .filter((i) => (i.title ?? '').trim() === want)
38	    .map((i) => ({ number: i.number, state: i.state }));
39	  if (!exact.length) return null;
40	  return exact.sort((a, b) => a.number - b.number)[0];
41	}
42	
43	// The tracker titled exactly `title`, or null if no issue carries it. Searches
44	// EVERY state: a tracker's resting state is closed, so a state-filtered lookup
45	// misses all of them.
46	export async function findTracker(gh, repo, title) {
47	  const want = title.trim();
48	  const q = encodeURIComponent(`repo:${repo} in:title "${want}"`);
49	  const { status, json } = await gh(`/search/issues?q=${q}&per_page=100`);
50	  if (status !== 200 || !Array.isArray(json?.items)) {
51	    throw new Error(`could not search for the tracker ${JSON.stringify(want)}: search returned ${status}`);
52	  }
53	  const exact = json.items.filter((i) => (i.title ?? '').trim() === want);
54	  const found = pickTracker(exact, want);
55	  return found ? { number: found.number, duplicates: exact.length - 1 } : null;
56	}
57	
58	// Create the tracker and close it — TWO calls, because issue creation always lands
59	// an issue open and ignores a `state` argument, so the single-call version left
60	// every tracker open across the fleet (#951).
61	export async function createTracker(gh, repo, title, body = null) {
62	  const want = title.trim();
63	  const created = await gh(`/repos/${repo}/issues`, {
64	    method: 'POST',
65	    body: { title: want, body: body ?? trackerSeedBody(want) },
66	  });
67	  if (created.status >= 300 || !created.json?.number) {
68	    throw new Error(`could not create the tracker ${JSON.stringify(want)}: create returned ${created.status}`);
69	  }
70	  const number = created.json.number;
71	  const closed = await gh(`/repos/${repo}/issues/${number}`, {
72	    method: 'PATCH',
73	    body: { state: 'closed', state_reason: 'completed' },
74	  });
75	  return { number, leftOpen: closed.status >= 300 };
76	}
77	
78	// Find it, or create it — for a task that writes to its tracker on every run and
79	// therefore always wants one. A task whose run may have nothing to record calls
80	// `findTracker` alone and creates only once it has something to write.
81	export async function findOrCreateTracker(gh, repo, title) {
82	  const found = await findTracker(gh, repo, title);
83	  if (found) return { ...found, created: false };
84	  const made = await createTracker(gh, repo, title);
85	  return { number: made.number, duplicates: 0, created: true, leftOpen: made.leftOpen };
86	}
87	
88	// What a freshly-created tracker says before its first run writes to it. It names
89	// its own contract, because whoever finds it next finds it closed and empty.
90	export function trackerSeedBody(title) {
91	  return [
92	    `Standing tracker for the Claudinite task that logs to **${title}**.`,
93	    '',
94	    'This issue is a living document: the **body** is rewritten to the current picture each run,',
95	    'and each run adds a dated comment. Its closed state carries no meaning — nothing opens,',
96	    'closes or reopens it, and no run should be read as "resolved" because it is closed.',
97	    '',
98	    '_No run has written here yet._',
99	  ].join('\n') + '\n';
100	}
101	
102	// Write a run's state to the tracker: the BODY replaced with the current picture,
103	// and optionally one dated comment appended. The state is untouched, in either
104	// direction — the body is the live picture, the comments are the trail.
105	export async function writeTracker(gh, repo, number, { body, comment = null } = {}) {
106	  if (body !== undefined && body !== null) {
107	    const patched = await gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { body } });
108	    if (patched.status >= 300) throw new Error(`could not refresh tracker #${number}: PATCH returned ${patched.status}`);
109	  }
110	  if (comment) {
111	    const posted = await gh(`/repos/${repo}/issues/${number}/comments`, { method: 'POST', body: { body: comment } });
112	    if (posted.status >= 300) throw new Error(`could not comment on tracker #${number}: POST returned ${posted.status}`);
113	  }
114	  return number;
115	}

